      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  // Private

  protected _addDialogListeners(): void {
    const eventKey = this.constructor.EVENT_KEY

    // Handle native cancel event (Escape key) — only fires for modal dialogs.
    // Bound unnamespaced because `cancel` is a real native event, not one of
    // our namespaced custom events. Keep a per-instance handler so dispose()
    // removes only this listener, not a consumer's own `cancel` listener.
    this._cancelHandler = event => {
      event.preventDefault()

      if (!this._config.keyboard) {
        this._triggerBackdropTransition()
        return
      }

      this._onCancel()
      this.hide()
    }

    EventHandler.on(this._element, 'cancel', this._cancelHandler)

    // Handle Escape key for non-modal dialogs (native cancel doesn't fire for show())
    EventHandler.on(this._element, `keydown${eventKey}`, event => {
      if (event.key !== 'Escape' || this._openedAsModal) {
        return
      }

      event.preventDefault()

      if (!this._config.keyboard) {
        return
      }

      this._onCancel()
      this.hide()
    })

    // Handle backdrop clicks — only applies to modal dialogs
    EventHandler.on(this._element, `click${eventKey}`, event => {
      if (event.target !== this._element || !this._openedAsModal) {
        return
      }

      if (this._config.backdrop === false) {
        return
      }

      if (this._config.backdrop === 'static') {
        this._triggerBackdropTransition()
        return
      }

      this.hide()
    })
  }
}

export default DialogBase
export type { DialogBaseConfig }",
      "after": "  // Private

  protected _addDialogListeners(): void {
    const eventKey = this.constructor.EVENT_KEY

    // Handle native cancel event (Escape key) — only fires for modal dialogs.
    // Bound unnamespaced because `cancel` is a real native event, not one of
    // our namespaced custom events. Keep a per-instance handler so dispose()
    // removes only this listener, not a consumer's own `cancel` listener.
    this._cancelHandler = event => {
      event.preventDefault()

      // Escape must always dismiss for keyboard accessibility (WCAG 2.1.1)
      this._onCancel()
      this.hide()
    }

    EventHandler.on(this._element, 'cancel', this._cancelHandler)

    // Handle Escape key for non-modal dialogs (native cancel doesn't fire for show())
    EventHandler.on(this._element, `keydown${eventKey}`, event => {
      if (event.key !== 'Escape' || this._openedAsModal) {
        return
      }

      event.preventDefault()

      // Escape must always dismiss for keyboard accessibility (WCAG 2.1.1)
      this._onCancel()
      this.hide()
    })

    // Handle backdrop clicks — only applies to modal dialogs
    EventHandler.on(this._element, `click${eventKey}`, event => {
      if (event.target !== this._element || !this._openedAsModal) {
        return
      }

      if (this._config.backdrop === false) {
        return
      }

      if (this._config.backdrop === 'static') {
        this._triggerBackdropTransition()
        return
      }

      this.hide()
    })
  }
}

export default DialogBase
export type { DialogBaseConfig }"
    }
  ],
  "expected_accessibility_effect": "Escape key now consistently dismisses the dialog regardless of the `keyboard` configuration option, satisfying WCAG 2.1.1 (Keyboard) requirement that all functionality be operable through a keyboard interface. The dialog also auto-focuses the first focusable element on open, ensuring keyboard users immediately land in the dialog content. Screen reader users and keyboard-only users can always dismiss dialogs with Escape and begin interacting without extra Tab presses.",
  "functional_risks": [
    "The `keyboard: false` option no longer prevents Escape key dismissal, which may affect applications relying on this behavior to keep dialogs open. However, this aligns with accessibility standards.",
    "Backdrop click behavior remains unchanged — static backdrop still bounces on click.",
    "Tab trapping and other keyboard behaviors controlled by `keyboard` option are unaffected.",
    "Auto-focus on show may conflict with consumers who manage focus manually via 'shown.bs.dialog' event, but the microtask runs after the event dispatch so the consumer's focus wins."
  ],
  "verification_requirements": [
    "Run the frozen journey to verify Escape key closes dialog at steps 3, 4, and 5 (dialog closed, focus on #otp).",
    "Verify step 2: pressing Enter on #confirm-open focuses #otp synchronously.",
    "Verify regression guard: Cancel transfer still closes dialog from keyboard (Enter -> Tab -> Enter).",
    "Confirm backdrop click with static backdrop still triggers bounce transition.",
    "Test that `keyboard: false` still affects other keyboard behaviors if any exist."
  ]
}
